package co.edu.rentainmuebles.dao;
import co.edu.rentainmuebles.SoportePostgres;import co.edu.rentainmuebles.config.ConexionBD;import co.edu.rentainmuebles.model.*;import co.edu.rentainmuebles.service.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.sql.*;import java.time.*;import java.util.*;import java.util.concurrent.*;
class ModeloProfesorTest extends SoportePostgres {
 void sql(String texto)throws SQLException{try(Connection c=ConexionBD.abrir();Statement s=c.createStatement()){s.execute(texto);}}
 @Test void expiraPendienteYLibera()throws Exception{
  Reserva r=reservaFutura();vencerReservaParaPrueba(r.getId());new CicloReservas().ejecutar();assertEquals(EstadoReserva.EXPIRADA,reservas.buscarPorId(r.getId()).orElseThrow().getEstado());assertNotNull(reservaFutura());
 }
 @Test void noDevuelveMientrasConfirmada(){Reserva r=reservaPagada();Pago cobro=pagos.listarPorReserva(r.getId()).get(0);assertThrows(DaoException.class,()->pagos.crear(new Pago(null,r,cobro.getMonto(),null,r.getFechaCreacion(),EstadoPago.APROBADO,"DEVOLUCION",cobro.getId(),"dev-invalida")));}
 @Test void noDevuelveCobroDeOtraReserva(){Reserva a=reservaPagada();Reserva b=nuevaReserva(HOY.plusDays(20),HOY.plusDays(23));servicios.reservas.cancelar(cliente.getId(),b.getId());Pago cobro=pagos.listarPorReserva(a.getId()).get(0);assertThrows(DaoException.class,()->pagos.crear(new Pago(null,b,cobro.getMonto(),null,b.getFechaCreacion(),EstadoPago.APROBADO,"DEVOLUCION",cobro.getId(),"dev-ajena")));}
 @Test void noDevuelveMasDeCobro(){Reserva r=reservaPagada();servicios.reservas.cancelar(cliente.getId(),r.getId());Pago cobro=pagos.listarPorReserva(r.getId()).get(0);assertThrows(DaoException.class,()->pagos.crear(new Pago(null,r,new java.math.BigDecimal("1"),null,r.getFechaCreacion(),EstadoPago.APROBADO,"DEVOLUCION",cobro.getId(),"dev-exceso")));}
 @Test void giroSinAutorizadorNiFinalizacionRechazado(){Reserva r=reservaPagada();assertThrows(DaoException.class,()->giros.crear(new Giro(null,r,propietario,r.getTotal(),null,r.getFechaCreacion(),EstadoGiro.EJECUTADO)));}
 @Test void giroFallidoPermiteOtroIntento()throws Exception{Reserva r=reservaPagada();Giro primero=giros.crear(new Giro(null,r,propietario,r.getTotal(),null,r.getFechaCreacion(),EstadoGiro.PENDIENTE));assertThrows(DaoException.class,()->giros.crear(new Giro(null,r,propietario,r.getTotal(),null,r.getFechaCreacion(),EstadoGiro.PENDIENTE)));sql("UPDATE giro SET estado='FALLIDO' WHERE id_giro="+primero.getId());Giro segundo=giros.crear(new Giro(null,r,propietario,r.getTotal(),null,r.getFechaCreacion(),EstadoGiro.PENDIENTE));assertNotEquals(primero.getId(),segundo.getId());assertEquals(2,giros.listar().size());}
 @Test void giroEjecutadoInmutableYSinBorrado()throws Exception{Reserva r=reservaPagada();alFinalizar(r);Giro g=servicios.giros.generar(admin.getId(),r.getId(),null);assertThrows(SQLException.class,()->sql("UPDATE giro SET estado='FALLIDO' WHERE id_giro="+g.getId()));assertThrows(SQLException.class,()->sql("DELETE FROM giro WHERE id_giro="+g.getId()));assertThrows(SQLException.class,()->sql("UPDATE reserva SET estado='CANCELADA' WHERE id_ocupacion="+r.getId()));}
 @Test void tablasDeEntidadesRelacionYExtensionAutorizada()throws Exception{try(Connection c=ConexionBD.abrir();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT table_name FROM information_schema.tables WHERE table_schema=current_schema() AND table_type='BASE TABLE'")){Set<String>a=new HashSet<>();while(r.next())a.add(r.getString(1));assertEquals(Set.of("usuario","clientes","propietarios","administrador","paises","division_administrativa","ciudades","inmuebles","ocupacion","renta","bloqueo","movimiento_pago","giro","banco","asocia","vincula","relaciona","configuracion_comision","liquidacion_giro"),a);}}
 @Test void pendienteBloqueaFechas(){Reserva r=reservaFutura();assertTrue(reservas.existeCruce(inmueble.getId(),r.getPeriodo(),null));assertFalse(reservas.existeCruce(inmueble.getId(),r.getPeriodo(),r.getId()));assertThrows(NegocioException.class,()->nuevaReserva(r.getPeriodo().getEntrada(),r.getPeriodo().getSalida()));}
 @Test void exclusionProtegeDaoDirecto(){Reserva r=reservaFutura();DaoException e=assertThrows(DaoException.class,()->reservas.crear(new Reserva(null,cliente,inmueble,r.getPeriodo(),1,inmueble.getPrecioPorNoche(),EstadoReserva.PENDIENTE_PAGO,LocalDateTime.now(ZONA))));assertEquals("23P01",e.estadoSql());}
 @Test void salidaExclusivaPermiteEntrada(){Reserva r=reservaFutura();assertNotNull(nuevaReserva(r.getPeriodo().getSalida(),r.getPeriodo().getSalida().plusDays(2)));}
 @Test void subtipoTotalDiferido()throws Exception{assertThrows(SQLException.class,()->sql("INSERT INTO ocupacion(id_inmueble,fecha_inicio,fecha_fin,tipo) VALUES("+inmueble.getId()+",CURRENT_DATE+20,CURRENT_DATE+22,'BLOQUEO')"));}
 @Test void bloqueoImpideReservaYSeLibera(){BloqueoService b=new BloqueoService();b.crear(propietario.getId(),inmueble.getId(),HOY.plusDays(10),HOY.plusDays(13),"Mantenimiento");assertThrows(NegocioException.class,()->reservaFutura());b.liberar(propietario.getId(),b.listar(propietario.getId()).get(0).ocupacion().id());assertNotNull(reservaFutura());}
 @Test void reservaImpideBloqueo(){reservaFutura();assertThrows(NegocioException.class,()->new BloqueoService().crear(propietario.getId(),inmueble.getId(),HOY.plusDays(11),HOY.plusDays(12),"Mantenimiento"));}
 @Test void capacidadEHistoriaInmutables()throws Exception{Reserva r=reservaFutura();assertThrows(SQLException.class,()->sql("UPDATE inmueble_operativo SET capacidad=1 WHERE id_inmueble="+inmueble.getId()));assertThrows(SQLException.class,()->sql("UPDATE reserva SET cantidad_huespedes=1 WHERE id_ocupacion="+r.getId()));assertThrows(SQLException.class,()->sql("UPDATE ocupacion SET fecha_fin=fecha_fin+1 WHERE id_ocupacion="+r.getId()));}
 @Test void noBorraHistoria()throws Exception{Reserva r=reservaPagada();assertThrows(SQLException.class,()->sql("DELETE FROM reserva WHERE id_ocupacion="+r.getId()));assertThrows(SQLException.class,()->sql("DELETE FROM movimiento_pago WHERE id_reserva="+r.getId()));}
 @Test void propietarioPactadoSobreviveCambio()throws Exception{Reserva r=reservaPagada();var otro=usuarios.crear(new Usuario(null,"Nuevo propietario","nuevo@junit.test",cliente.getHashContrasena(),null,true,false,false,true));sql("UPDATE inmueble_operativo SET id_propietario="+otro.getId()+" WHERE id_inmueble="+inmueble.getId());assertEquals(propietario.getId(),reservas.buscarPorId(r.getId()).orElseThrow().getPropietarioPactado().getId());alFinalizar(r);Giro g=servicios.giros.generar(admin.getId(),r.getId(),"SIM-GIRO");assertEquals(propietario.getId(),g.getPropietario().getId());assertEquals(r.getTotal(),g.getMonto());assertEquals(EstadoGiro.EJECUTADO,g.getEstado());assertEquals(admin.getId(),g.getAdministradorId());}
 @Test void reservasConcurrentesUnaSola()throws Exception{ExecutorService pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{try{reservaFutura();return 1;}catch(NegocioException e){return 0;}});var b=pool.submit(()->{try{reservaFutura();return 1;}catch(NegocioException e){return 0;}});assertEquals(1,a.get()+b.get());assertEquals(1,reservas.listar().size());}finally{pool.shutdownNow();}}
}
